"""Render the frozen matched results as a portable HTML report."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
r=json.loads((ROOT/'final-results.json').read_text())
selected=[m for m in r['primary_metrics'] if m['benchmark'] not in ('discoveryworld','lingoly_no_context')]
data={'models':r['models'],'metrics':selected,'paired':r['lingoly_paired_context']}
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Codex benchmark sprint results</title><style>
body{margin:0;color:var(--foreground,#d9e0ec);font:14px/1.5 var(--font-sans,system-ui)}p{margin:0 0 16px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:20px}.stat{border:1px solid var(--border,#414754);border-radius:var(--radius,10px);padding:16px}.stat strong{display:block;font-size:28px;line-height:1.2}.stat span,.muted,small{color:var(--muted-foreground,#9ba4b6)}.stat span{font-size:12px}.note{color:var(--muted-foreground,#9ba4b6);font-size:12px}table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:13px}th,td{text-align:right;padding:11px 5px;border-bottom:1px solid var(--border,#414754);vertical-align:middle}th:first-child,td:first-child{text-align:left}th{font-size:12px;font-weight:500;color:var(--muted-foreground,#9ba4b6)}th:first-child{width:31%}th:nth-child(2){width:13%}td small{display:block;font-size:11px;line-height:1.3;margin-top:2px}a{color:var(--foreground,#d9e0ec);text-decoration:none}a:hover{text-decoration:underline}.best{font-weight:750;color:var(--success,#66d6a0)}button{margin:14px 0 10px;border:1px solid var(--border,#414754);border-radius:6px;background:var(--secondary,#262f40);color:var(--foreground,#d9e0ec);padding:8px 10px;font:12px var(--font-sans,system-ui);cursor:pointer}.conclusion{border-left:3px solid var(--chart-1,#6a9cfa);padding-left:14px;margin:24px 0}.conclusion p{margin:0 0 8px}details{border-top:1px solid var(--border,#414754);padding-top:14px;margin-top:18px}summary{cursor:pointer;font-weight:600}.context{display:grid;grid-template-columns:42px 1fr 92px;gap:10px;align-items:center;margin:13px 0}.track{height:14px;background:var(--muted,#343d4c);position:relative;border-radius:3px;overflow:hidden}.full{position:absolute;inset:0 auto 0 0;background:var(--chart-1,#6a9cfa)}.none{position:absolute;inset:4px auto 4px 0;background:var(--foreground,#d9e0ec)}.context small{font-size:11px;text-align:right}.methods{font-size:12px;color:var(--muted-foreground,#9ba4b6);margin-top:14px}.methods p{margin-bottom:10px}@media(max-width:500px){body{font-size:13px}.stat{padding:10px}.stat strong{font-size:22px}.stat span{font-size:10px}table{font-size:11px}td,th{padding:10px 3px}th{font-size:10px}td small{font-size:10px}.context{grid-template-columns:35px 1fr 85px;gap:6px}}
</style></head><body>
<div class="stats"><div class="stat"><strong>2,283</strong><span>valid completed trials</span></div><div class="stat"><strong>569</strong><span>shared cases across all four models</span></div><div class="stat"><strong>95%</strong><span>account usage cutoff, credits unchanged</span></div></div>
<p class="note">GPT-6.1 Sol · GPT-6 Astra · GPT-6.1 Terra · GPT-6 Luna<br>High reasoning, default speed, Codex subscription. Time-bounded subsets, not full benchmark runs.</p>
<table><thead><tr><th>Benchmark</th><th>N</th><th>Sol</th><th>Astra</th><th>Terra</th><th>Luna</th></tr></thead><tbody id="scores"></tbody></table>
<button id="ling-toggle" aria-pressed="false">LingOly: show whole-group accuracy</button>
<p class="note">N is identical across models in each row. Hover a percentage for its exact count. LingOly initially shows accuracy across 490 answer parts from 76 groups.</p>
<div class="conclusion"><p>Astra completed all 27 matched harder science tasks. Sol completed 25, Terra 24, Luna 10.</p><p class="note">BBEH, mixed-rule KOR and LingOly also separated the models. Sol and Astra were close on several static subsets. PlanBench was 100% for Sol, Astra and Terra in this sample.</p></div>
<details><summary>Paired LingOly context check</summary><p class="note" style="margin-top:12px">46 identical question groups, 333 answer parts. Blue shows supplied context; the thin light bar shows no context. Context dependence does not establish absence of training contamination.</p><div id="context"></div></details>
<details><summary>Scope, source quirks and verification</summary><div class="methods"><p>The main batch completed 2,158 trials and science completed 125. Seven interrupted trials, one retained request-rate failure and 168 science trials marked not run are outside scored comparisons. Seven valid completions lacked all four counterparts. The 28 integrated pilots and earlier setup attempts are separate.</p><p>DiscoveryWorld results cover seven themes and completed seeds 0 and 1. Later seeds were queued but not completed. Each harder task allowed 1,000 actions. The custom agent used official completion and procedural scores, with no knowledge judge. Easy completion was 100% for all four models on four shared tasks.</p><p>567 groups have byte-identical prompts. Two Space Sick groups vary only in runtime object IDs and observation-list order after normalization; task preambles and official hypotheses match. The JSON also gives the result with these two groups excluded.</p><p>FANToM is a deterministic inaccessible-information subset, not the published All score. Mixed KOR requires every question in a prompt to be correct. KOR preserves 12 source gold answers rejected by its scorer. LingOly preserves empty-label behavior and reports a nonempty-label sensitivity. PlanBench uses a simulator checked against all 110 official reference plans.</p><p>All 2,283 complete model resolutions checked. 53 representative correct and wrong responses rescored. All 125 science tool boundaries audited. 21 validation tests passed. No owned model workers remain. Exact counts and full precision are in the CSV and JSON artifacts.</p></div></details>
<script>const DATA=__DATA__;let groups=false;const names={"gpt-6.1-sol":"Sol","gpt-6-astra":"Astra","gpt-6.1-terra":"Terra","gpt-6-luna":"Luna"};function draw(){const benches=[...new Set(DATA.metrics.map(x=>x.benchmark))];document.getElementById('scores').innerHTML=benches.map(b=>{const ms=DATA.models.map(model=>DATA.metrics.find(x=>x.benchmark===b&&x.model===model));const ling=b==='lingoly';const rates=ms.map(x=>groups&&ling?x.case_accuracy:x.primary_accuracy);const best=Math.max(...rates);const n=groups&&ling?ms[0].matched_cases:ms[0].primary_total;return `<tr><td><a href="${ms[0].source}">${ms[0].title}</a><small>${groups&&ling?'All parts correct':ms[0].metric}</small></td><td>${n}<small>${ling?(groups?'groups':'parts'):b==='discoveryworld_advanced'?'tasks':'cases'}</small></td>${ms.map((m,i)=>{const k=groups&&ling?m.correct_cases:m.primary_correct;return `<td class="${rates[i]===best?'best':''}" title="${k}/${n}">${(100*rates[i]).toFixed(1)}%</td>`}).join('')}</tr>`}).join('');const btn=document.getElementById('ling-toggle');btn.textContent=groups?'LingOly: show answer-part accuracy':'LingOly: show whole-group accuracy';btn.setAttribute('aria-pressed',String(groups))}document.getElementById('ling-toggle').onclick=()=>{groups=!groups;draw()};document.getElementById('context').innerHTML=DATA.paired.map(x=>`<div class="context"><span>${names[x.model]}</span><div class="track"><div class="full" style="width:${100*x.full_accuracy}%"></div><div class="none" style="width:${100*x.no_context_accuracy}%"></div></div><small>${(100*x.no_context_accuracy).toFixed(1)}% → ${(100*x.full_accuracy).toFixed(1)}%</small></div>`).join('');draw();console.log('Verified render data',DATA.models.length,'models',new Set(DATA.metrics.map(x=>x.benchmark)).size,'benchmarks',DATA.paired.length,'context pairs');</script></body></html>'''
(ROOT/'results.html').write_text(page.replace('__DATA__',json.dumps(data)))
print('wrote results.html')
